\"\"\"Minimal, standard-library-only client for OpenAI's Responses API.

Usage:
    export OPENAI_API_KEY=\"sk-...\"
    python3 openai_client.py \"Summarize the plot of Hamlet in one sentence.\"

Or from Python:
    from openai_client import OpenAIClient
    client = OpenAIClient()
    print(client.ask(\"Hello"'!"))

Privacy notes:
- The API key is read from the OPENAI_API_KEY environment variable (or passed
  explicitly) and is never written to disk or included in logs/errors.
- Prompts are sent only to the configured OpenAI endpoint over HTTPS.
- Requests set "store": false by default so OpenAI does not retain the
  conversation for later retrieval via the API.
"""

from __future__ import annotations

import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any, Dict, List, Optional

DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = "gpt-4.1-mini"
DEFAULT_TIMEOUT = 60.0


class OpenAIClientError(Exception):
    """Raised when the API returns an error or the response is malformed."""

    def __init__(self, message: str, status: Optional[int] = None, body: Optional[Any] = None):
        super().__init__(message)
        self.status = status
        self.body = body


class OpenAIClient:
    """Send text prompts to the Responses API using only the standard library."""

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        model: str = DEFAULT_MODEL,
        base_url: str = DEFAULT_BASE_URL,
        timeout: float = DEFAULT_TIMEOUT,
        store: bool = False,
    ) -> None:
        key = api_key if api_key is not None else os.environ.get("OPENAI_API_KEY", "")
        key = key.strip()
        if not key:
            raise OpenAIClientError(
                "No API key provided. Set the OPENAI_API_KEY environment variable "
                "or pass api_key=... to OpenAIClient()."
            )
        self._api_key = key
        self.model = model
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout
        self.store = store

    def __repr__(self) -> str:
        return f"OpenAIClient(model={self.model!r}, base_url={self.base_url!r})"

    def create_response(
        self,
        prompt: str,
        *,
        instructions: Optional[str] = None,
        model: Optional[str] = None,
        temperature: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        previous_response_id: Optional[str] = None,
        extra: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Call POST /responses and return the full parsed JSON response."""
        if not isinstance(prompt, str) or not prompt.strip():
            raise ValueError("prompt must be a non-empty string")

        payload: Dict[str, Any] = {
            "model": model or self.model,
            "input": prompt,
            "store": self.store,
        }
        if instructions is not None:
            payload["instructions"] = instructions
        if temperature is not None:
            payload["temperature"] = temperature
        if max_output_tokens is not None:
            payload["max_output_tokens"] = max_output_tokens
        if previous_response_id is not None:
            payload["previous_response_id"] = previous_response_id
        if extra:
            payload.update(extra)

        return self._post("/responses", payload)

    def ask(self, prompt: str, **kwargs: Any) -> str:
        """Send a prompt and return the model'"'s text output.\"\"\"
        response = self.create_response(prompt, **kwargs)
        return extract_output_text(response)

    def _post(self, path: str, payload: Dict[str, Any]) -> Dict[str, Any]:
        data = json.dumps(payload).encode(\"utf-8\")
        request = urllib.request.Request(
            self.base_url + path,
            data=data,
            method=\"POST\",
            headers={
                \"Authorization\": f\"Bearer {self._api_key}\",
                \"Content-Type\": \"application/json\",
                \"Accept\": \"application/json\",
                \"User-Agent\": \"openai_client.py (stdlib)\",
            },
        )
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as resp:
                raw = resp.read()
                status = resp.status
        except urllib.error.HTTPError as err:
            raw = err.read()
            body = _safe_json(raw)
            message = _error_message(body) or f\"HTTP {err.code}\"
            raise OpenAIClientError(f\"OpenAI API error: {message}\", status=err.code, body=body) from None
        except urllib.error.URLError as err:
            raise OpenAIClientError(f\"Network error: {err.reason}\") from None

        body = _safe_json(raw)
        if not isinstance(body, dict):
            raise OpenAIClientError(\"Unexpected non-JSON response from API\", status=status, body=body)
        return body


def extract_output_text(response: Dict[str, Any]) -> str:
    \"\"\"Concatenate all output_text segments from a Responses API result.\"\"\"
    if isinstance(response.get(\"output_text\"), str):
        return response[\"output_text\"]

    parts: List[str] = []
    for item in response.get(\"output\", []) or []:
        if item.get(\"type\") "'!= "message":
            continue
        for content in item.get("content", []) or []:
            if content.get("type") == "output_text":
                parts.append(content.get("text", ""))
    return "".join(parts)


def _safe_json(raw: bytes) -> Any:
    try:
        return json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return raw.decode("utf-8", errors="replace")


def _error_message(body: Any) -> Optional[str]:
    if isinstance(body, dict):
        err = body.get("error")
        if isinstance(err, dict):
            return err.get("message")
        if isinstance(err, str):
            return err
    return None


def _main(argv: List[str]) -> int:
    if len(argv) > 1 and argv[1] not in ("-h", "--help"):
        prompt = " ".join(argv[1:])
    elif len(argv) == 1 and not sys.stdin.isatty():
        prompt = sys.stdin.read()
    else:
        print(__doc__.strip(), file=sys.stderr)
        return 2

    model = os.environ.get("OPENAI_MODEL", DEFAULT_MODEL)
    try:
        client = OpenAIClient(model=model)
        print(client.ask(prompt))
    except OpenAIClientError as err:
        print(f"error: {err}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(_main(sys.argv))
